<?php
declare(strict_types=1);
namespace Morshed\Product;
use Morshed\Core\{Database,Audit,Security,Problem};
/** Called beneath the existing installation transaction lock; never acknowledges before commit. */
final class ConsultationCredits
{
 public function __construct(private Database $db){}
 private function locked():void {if(!$this->db->pdo->inTransaction())throw new \LogicException('Credit mutation requires the consultation transaction');}
 public function cycle(?array $policy=null,?int $now=null):string {$p=$policy??(new Membership($this->db))->policy();$d=(new \DateTimeImmutable('@'.($now??time())))->setTimezone(new \DateTimeZone($p['timezone']));$anchor=$d->setDate((int)$d->format('Y'),(int)$d->format('m'),(int)$p['cycle_day'])->setTime(0,0);if($d<$anchor)$anchor=$anchor->modify('-1 month');return $anchor->format('Y-m-d');}
 public function balance(string $uid,?string $excludeBooking=null):array {
  $m=new Membership($this->db);$p=$m->policy();$profile=$m->profile($uid);$cycle=$this->cycle($p);$quota=(int)$p[$profile['tier']==='member'?'member_quota':'independent_quota'];
  $counts=$this->db->one("SELECT COALESCE(SUM(r.state='held'),0) AS held,COALESCE(SUM(r.state='spent' AND r.cycle_key=?),0) AS spent,COALESCE(SUM(r.state='held' AND a.booking_id IS NULL),0) AS base_held,COALESCE(SUM(r.state='spent' AND r.cycle_key=? AND a.booking_id IS NULL),0) AS base_spent FROM m_credit_reservations r LEFT JOIN m_credit_allocations a ON a.booking_id=r.booking_id WHERE r.user_id=?",[$cycle,$cycle,$uid]);
  $legacy=(int)$this->db->run("SELECT COUNT(*) FROM m_bookings b WHERE b.user_id=? AND b.id<>? AND (b.state='confirmed' OR (b.state='pending' AND b.expires_at>?)) AND NOT EXISTS(SELECT 1 FROM m_credit_reservations r WHERE r.booking_id=b.id)",[$uid,$excludeBooking??'',time()])->fetchColumn();
  $grants=$this->db->all("SELECT g.id,g.amount-(SELECT COUNT(*) FROM m_credit_allocations a JOIN m_credit_reservations r ON r.booking_id=a.booking_id AND r.state IN ('held','spent') WHERE a.grant_id=g.id) AS available FROM m_credit_grants g WHERE g.user_id=? AND g.expires_at>? ORDER BY g.expires_at,g.id",[$uid,time()]);$bonus=array_sum(array_map(fn($g)=>max(0,(int)$g['available']),$grants));$baseAvailable=max(0,$quota-(int)$counts['base_held']-(int)$counts['base_spent']-$legacy);
  return ['quota'=>$quota,'held'=>(int)$counts['held']+$legacy,'spent'=>(int)$counts['spent'],'bonus'=>$bonus,'available'=>$baseAvailable+$bonus,'base_available'=>$baseAvailable,'grants'=>$grants,'cycle'=>$cycle,'tier'=>$profile['tier'],'novice'=>$profile['novice'],'enabled'=>(bool)$p['enabled'],'timezone'=>$p['timezone'],'cycle_day'=>(int)$p['cycle_day']];
 }
 public function check(string $uid,string $mentor):void {$this->locked();$m=new Membership($this->db);$p=$m->policy();if(!$p['enabled'])return;$elig=$m->eligibility($uid,$mentor);if(!$elig['allowed'])throw new Problem('CONSULTATION_RESTRICTED',$elig['reason'],403);if((int)$this->db->run("SELECT COUNT(*) FROM m_bookings WHERE user_id=? AND state='pending' AND expires_at>?",[$uid,time()])->fetchColumn()>=(int)$p['max_pending'])throw new Problem('PENDING_LIMIT','سقف درخواست‌های در حال بررسی شما تکمیل است.',409);if($this->balance($uid)['available']<1)throw new Problem('CREDIT_EXHAUSTED','اعتبار قابل استفادهٔ مشاوره شما تمام شده است.',409);}
 public function hold(array $booking,array $actor):void {$this->locked();$p=(new Membership($this->db))->policy();if(!$p['enabled'])return;if($this->db->one('SELECT booking_id FROM m_credit_reservations WHERE booking_id=?',[$booking['id']]))return;
  // Exclude the just-created booking from the legacy pending count while allocating.
  $balance=$this->balance($booking['user_id'],$booking['id']);$base=$balance['base_available'];$grant=null;if($base<1){foreach($balance['grants'] as $g){if((int)$g['available']>0){$grant=$g['id'];break;}}if(!$grant)throw new Problem('CREDIT_EXHAUSTED','اعتبار قابل استفاده کافی نیست.',409);}
  $this->db->run("INSERT INTO m_credit_reservations VALUES(?,?,?,'held',?,?)",[$booking['id'],$booking['user_id'],$this->cycle($p),time(),time()]);if($grant)$this->db->run('INSERT INTO m_credit_allocations VALUES(?,?)',[$booking['id'],$grant]);$this->event($booking['user_id'],$booking['id'],'held','رزرو موقت اعتبار درخواست',$actor['user_id']);
 }
 public function settle(array $b,string $next,?string $actor,string $reason=''):void {$this->locked();$r=$this->db->one('SELECT * FROM m_credit_reservations WHERE booking_id=? FOR UPDATE',[$b['id']]);if(!$r||$r['state']!=='held')return;$state=match($next){'rejected','expired'=>'released','completed','user_no_show'=>'spent','mentor_no_show'=>'released','cancelled'=>($actor===$b['user_id']&&((int)$b['starts_at']-time())<(int)(new Membership($this->db))->policy()['cancel_hours']*3600?'spent':'released'),default=>null};if(!$state)return;$this->db->run('UPDATE m_credit_reservations SET state=?,cycle_key=?,updated_at=? WHERE booking_id=?',[$state,$state==='spent'?$this->cycle():$r['cycle_key'],time(),$b['id']]);$this->event($b['user_id'],$b['id'],$state,$reason?:$next,$actor);(new Audit($this->db))->notify($b['user_id'],'اعتبار مشاوره به‌روز شد',$state==='spent'?'یک اعتبار برای این جلسه مصرف شد.':'اعتبار رزروشدهٔ این جلسه آزاد شد.','/account');}
 private function event(string $uid,?string $bid,string $event,string $reason,?string $actor):void {$this->db->run('INSERT IGNORE INTO m_credit_events(user_id,booking_id,event,reason,actor_id,created_at) VALUES(?,?,?,?,?,?)',[$uid,$bid,$event,$reason,$actor,time()]);}
 public function grant(array $a,array $d):string {(new Membership($this->db))->central($a);return (new Membership($this->db))->write(function()use($a,$d){$id=Policy::text($d['id']??'',32);if(!Security::validId($id))throw new Problem('INVALID_INPUT','شناسهٔ اعطای اعتبار معتبر نیست.');$uid=Policy::text($d['user_id']??'',32);$amount=Policy::integer($d['amount']??'',1,1000);$expires=Consultations::localTimestamp(Policy::text($d['expires_local']??'',16));if($expires<=time())throw new Problem('INVALID_DATE','زمان انقضا باید در آینده باشد.');$reason=Policy::text($d['reason']??'',1000,3);if(!$this->db->one("SELECT id FROM m_users WHERE id=? AND status='active'",[$uid]))throw new Problem('NOT_FOUND','کاربر پیدا نشد.',404);$old=$this->db->one('SELECT * FROM m_credit_grants WHERE id=?',[$id]);if($old){if($old['user_id']!==$uid||(int)$old['amount']!==$amount||(int)$old['expires_at']!==$expires||$old['reason']!==$reason)throw new Problem('IDEMPOTENCY_CONFLICT','این اعطا قبلاً با اطلاعات دیگری ثبت شده است.',409);return $id;}$this->db->run('INSERT INTO m_credit_grants VALUES(?,?,?,?,?,?,?)',[$id,$uid,$amount,$expires,$reason,$a['user_id'],time()]);$this->event($uid,null,'granted',$amount.' اعتبار: '.$reason,$a['user_id']);(new Audit($this->db))->notify($uid,'اعتبار تشویقی مشاوره',$amount.' اعتبار تا '.Consultations::sessionLabel($expires).' به شما تعلق گرفت.','/account');return $id;});}
}
